/*
 * wcinit - WinCraft OS init (PID 1)
 *
 * A deliberately small init: mount the kernel filesystems, run one boot
 * script, supervise a handful of services, and bring the machine down cleanly.
 *
 *   /etc/wincraft/rc.boot        one-shot system bring-up (shell)
 *   /etc/wincraft/services       "<name> <respawn|once> <command...>" per line
 *   /run/wincraft/services       same format, generated by rc.boot at run time
 *   /etc/wincraft/rc.shutdown    one-shot teardown (shell)
 *   /run/wcinit.ctl              control FIFO: poweroff | reboot | halt |
 *                                priv <helper> [args...]
 *
 * "priv" runs /usr/lib/wincraft/priv.d/<helper> as root. It is how the
 * unprivileged desktop asks for privileged work (e.g. installing to disk):
 * helpers are root-owned, validate their own arguments, and only members of
 * the group owning the FIFO can reach them.
 *
 * Signals follow the busybox/sysvinit convention so stock poweroff/reboot
 * applets work: SIGUSR1 halt, SIGUSR2 poweroff, SIGTERM/SIGINT reboot.
 *
 * SPDX-License-Identifier: MIT
 */
#define _GNU_SOURCE
#include <ctype.h>
#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <signal.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/mount.h>
#include <sys/reboot.h>
#include <sys/signalfd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

#define RC_BOOT      "/etc/wincraft/rc.boot"
#define RC_SHUTDOWN  "/etc/wincraft/rc.shutdown"
#define SERVICES     "/etc/wincraft/services"
#define SERVICES_RUN "/run/wincraft/services"    /* written by rc.boot */
#define CTL_FIFO     "/run/wcinit.ctl"
#define CTL_GROUP    "wheel"
#define PRIV_DIR     "/usr/lib/wincraft/priv.d"
#define LOG_DIR      "/run/log"
#define MAX_SVC      32
#define ENV_PATH     "PATH=/usr/local/bin:/usr/bin"

struct svc {
    char name[32];
    char *cmd;
    int respawn;
    pid_t pid;
    time_t started;
    time_t next_start;      /* 0 = not scheduled */
    int fails;
};

static struct svc svcs[MAX_SVC];
static int nsvc;
static int console_fd = -1;

static void say(const char *fmt, ...)
{
    char buf[512];
    va_list ap;
    int n;

    va_start(ap, fmt);
    n = vsnprintf(buf, sizeof(buf) - 1, fmt, ap);
    va_end(ap);
    if (n < 0)
        return;
    if (n > (int)sizeof(buf) - 2)
        n = sizeof(buf) - 2;
    buf[n++] = '\n';
    if (console_fd >= 0 && write(console_fd, buf, n) < 0) { /* nothing to do */ }
}

static time_t now(void)
{
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec;
}

static void try_mount(const char *src, const char *dst, const char *type,
                      unsigned long flags, const char *data)
{
    mkdir(dst, 0755);
    if (mount(src, dst, type, flags, data) < 0 && errno != EBUSY)
        say("wcinit: mount %s: %s", dst, strerror(errno));
}

static void early_mounts(void)
{
    try_mount("proc", "/proc", "proc", MS_NOSUID | MS_NODEV | MS_NOEXEC, NULL);
    try_mount("sysfs", "/sys", "sysfs", MS_NOSUID | MS_NODEV | MS_NOEXEC, NULL);
    try_mount("devtmpfs", "/dev", "devtmpfs", MS_NOSUID, "mode=0755");
    try_mount("devpts", "/dev/pts", "devpts", MS_NOSUID | MS_NOEXEC, "gid=5,mode=620,ptmxmode=666");
    try_mount("tmpfs", "/dev/shm", "tmpfs", MS_NOSUID | MS_NODEV, "mode=1777");
    try_mount("tmpfs", "/run", "tmpfs", MS_NOSUID | MS_NODEV, "mode=0755");
    try_mount("tmpfs", "/tmp", "tmpfs", MS_NOSUID | MS_NODEV, "mode=1777");
    mkdir(LOG_DIR, 0755);
}

static void child_setup(const char *logname)
{
    sigset_t none;
    char path[128];
    int fd;

    sigemptyset(&none);
    sigprocmask(SIG_SETMASK, &none, NULL);
    setsid();

    fd = open("/dev/null", O_RDONLY);
    if (fd >= 0) { dup2(fd, 0); if (fd > 2) close(fd); }
    snprintf(path, sizeof(path), LOG_DIR "/%s.log", logname);
    fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0)
        fd = open("/dev/console", O_WRONLY);
    if (fd >= 0) { dup2(fd, 1); dup2(fd, 2); if (fd > 2) close(fd); }
    putenv(ENV_PATH);
}

/* Run a script to completion, with its output on the console. */
static void run_script(const char *path)
{
    pid_t pid;
    int status;

    if (access(path, X_OK) != 0)
        return;
    pid = fork();
    if (pid == 0) {
        sigset_t none;

        sigemptyset(&none);
        sigprocmask(SIG_SETMASK, &none, NULL);
        putenv(ENV_PATH);
        execl(path, path, (char *)NULL);
        _exit(127);
    }
    if (pid > 0)
        while (waitpid(pid, &status, 0) < 0 && errno == EINTR)
            ;
}

static void load_services(const char *path)
{
    char line[1024];
    FILE *f = fopen(path, "r");

    if (!f)
        return;
    while (nsvc < MAX_SVC && fgets(line, sizeof(line), f)) {
        char name[32], mode[16];
        int off = 0;
        char *cmd;

        if (line[0] == '#' || sscanf(line, "%31s %15s %n", name, mode, &off) < 2 || !off)
            continue;
        cmd = line + off;
        cmd[strcspn(cmd, "\n")] = 0;
        if (!*cmd)
            continue;
        strcpy(svcs[nsvc].name, name);
        svcs[nsvc].cmd = strdup(cmd);
        svcs[nsvc].respawn = !strcmp(mode, "respawn");
        svcs[nsvc].next_start = 1;
        nsvc++;
    }
    fclose(f);
}

static void start_service(struct svc *s)
{
    pid_t pid = fork();

    if (pid == 0) {
        child_setup(s->name);
        execl("/bin/sh", "sh", "-c", s->cmd, (char *)NULL);
        _exit(127);
    }
    if (pid < 0) {
        s->next_start = now() + 2;
        return;
    }
    s->pid = pid;
    s->started = now();
    s->next_start = 0;
}

static void reap(void)
{
    pid_t pid;
    int status, i;

    while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
        for (i = 0; i < nsvc; i++) {
            struct svc *s = &svcs[i];

            if (s->pid != pid)
                continue;
            s->pid = 0;
            if (!s->respawn)
                break;
            /* Back off when a service keeps dying right after start. */
            if (now() - s->started < 5)
                s->fails = s->fails < 10 ? s->fails + 1 : 10;
            else
                s->fails = 0;
            s->next_start = now() + (s->fails ? s->fails : 0) + 1;
            break;
        }
    }
}

static void run_priv(char *args)
{
    char *argv[16], path[256];
    int argc = 0;
    char *tok, *p;
    pid_t pid;

    for (tok = strtok(args, " \t"); tok && argc < 15; tok = strtok(NULL, " \t"))
        argv[argc++] = tok;
    argv[argc] = NULL;
    if (!argc)
        return;
    for (p = argv[0]; *p; p++)
        if (!islower((unsigned char)*p) && !isdigit((unsigned char)*p) && *p != '-')
            return;
    snprintf(path, sizeof(path), PRIV_DIR "/%s", argv[0]);
    if (access(path, X_OK) != 0)
        return;

    pid = fork();
    if (pid == 0) {
        char logname[64];

        snprintf(logname, sizeof(logname), "priv-%s", argv[0]);
        child_setup(logname);
        execv(path, argv);
        _exit(127);
    }
}

static void do_shutdown(int how)
{
    struct timespec ts = { 0, 100 * 1000 * 1000 };
    int i;

    say("wcinit: shutting down");
    run_script(RC_SHUTDOWN);

    kill(-1, SIGTERM);
    for (i = 0; i < 30; i++) {
        while (waitpid(-1, NULL, WNOHANG) > 0)
            ;
        if (kill(-1, 0) < 0 && errno == ESRCH)
            break;
        nanosleep(&ts, NULL);
    }
    kill(-1, SIGKILL);
    while (waitpid(-1, NULL, WNOHANG) > 0)
        ;

    sync();
    if (fork() == 0) {
        execl("/usr/bin/umount", "umount", "-a", "-r", (char *)NULL);
        _exit(127);
    }
    wait(NULL);
    mount(NULL, "/", NULL, MS_REMOUNT | MS_RDONLY, NULL);
    sync();
    reboot(how);
    for (;;)
        pause();
}

static void handle_ctl(int fd)
{
    static char buf[512];
    static size_t len;
    ssize_t n;
    char *nl;

    n = read(fd, buf + len, sizeof(buf) - 1 - len);
    if (n <= 0)
        return;
    len += n;
    buf[len] = 0;
    while ((nl = strchr(buf, '\n'))) {
        *nl = 0;
        if (!strcmp(buf, "poweroff"))
            do_shutdown(RB_POWER_OFF);
        else if (!strcmp(buf, "reboot"))
            do_shutdown(RB_AUTOBOOT);
        else if (!strcmp(buf, "halt"))
            do_shutdown(RB_HALT_SYSTEM);
        else if (!strncmp(buf, "priv ", 5))
            run_priv(buf + 5);
        len -= (nl + 1 - buf);
        memmove(buf, nl + 1, len + 1);
    }
    if (len >= sizeof(buf) - 1)
        len = 0;
}

/* Look a group up in /etc/group directly: wcinit is static, so no NSS. */
static gid_t group_id(const char *name)
{
    char line[512];
    size_t len = strlen(name);
    gid_t gid = 0;
    FILE *f = fopen("/etc/group", "r");

    if (!f)
        return 0;
    while (fgets(line, sizeof(line), f)) {
        char *p;

        if (strncmp(line, name, len) || line[len] != ':')
            continue;
        p = strchr(line + len + 1, ':');
        if (p)
            gid = (gid_t)strtoul(p + 1, NULL, 10);
        break;
    }
    fclose(f);
    return gid;
}

static int open_ctl(void)
{
    int fd;

    unlink(CTL_FIFO);
    if (mkfifo(CTL_FIFO, 0620) < 0)
        return -1;
    if (chown(CTL_FIFO, 0, group_id(CTL_GROUP)) < 0) { /* root-only then */ }
    chmod(CTL_FIFO, 0620);
    /* O_RDWR so the FIFO never reports EOF when writers come and go. */
    fd = open(CTL_FIFO, O_RDWR | O_NONBLOCK | O_CLOEXEC);
    return fd;
}

int main(void)
{
    struct pollfd pfd[2];
    sigset_t mask;
    int sfd, cfd, i;

    if (getpid() != 1) {
        fprintf(stderr, "wcinit: must be run as PID 1\n");
        return 1;
    }

    umask(022);
    early_mounts();
    console_fd = open("/dev/console", O_WRONLY | O_NOCTTY | O_CLOEXEC);
    if (chdir("/") < 0) { /* keep going */ }
    setsid();
    putenv(ENV_PATH);

    sigfillset(&mask);
    sigprocmask(SIG_BLOCK, &mask, NULL);
    sigemptyset(&mask);
    sigaddset(&mask, SIGCHLD);
    sigaddset(&mask, SIGTERM);
    sigaddset(&mask, SIGINT);
    sigaddset(&mask, SIGUSR1);
    sigaddset(&mask, SIGUSR2);
    sfd = signalfd(-1, &mask, SFD_CLOEXEC | SFD_NONBLOCK);
    reboot(RB_DISABLE_CAD);     /* Ctrl-Alt-Del -> SIGINT to us */

    say("WinCraft OS is starting...");
    run_script(RC_BOOT);

    cfd = open_ctl();
    load_services(SERVICES);
    load_services(SERVICES_RUN);
    if (!nsvc)
        say("wcinit: no services configured in " SERVICES);

    pfd[0].fd = sfd;
    pfd[0].events = POLLIN;
    pfd[1].fd = cfd;
    pfd[1].events = POLLIN;

    for (;;) {
        time_t t = now();
        int timeout = -1;

        for (i = 0; i < nsvc; i++) {
            struct svc *s = &svcs[i];

            if (s->pid || !s->next_start)
                continue;
            if (s->next_start <= t)
                start_service(s);
            else if (timeout < 0 || (s->next_start - t) * 1000 < timeout)
                timeout = (s->next_start - t) * 1000;
        }

        if (poll(pfd, cfd >= 0 ? 2 : 1, timeout) < 0 && errno != EINTR)
            continue;

        if (pfd[0].revents & POLLIN) {
            struct signalfd_siginfo si;

            while (read(sfd, &si, sizeof(si)) == sizeof(si)) {
                switch (si.ssi_signo) {
                case SIGCHLD: reap(); break;
                case SIGUSR1: do_shutdown(RB_HALT_SYSTEM); break;
                case SIGUSR2: do_shutdown(RB_POWER_OFF); break;
                case SIGTERM:
                case SIGINT:  do_shutdown(RB_AUTOBOOT); break;
                }
            }
        }
        if (cfd >= 0 && (pfd[1].revents & POLLIN))
            handle_ctl(cfd);
        reap();
    }
}
